-- For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. — John 3:16 (KJV)
{-# LANGUAGE DataKinds, KindSignatures, PolyKinds #-}
module RepPolyDataFieldChirho where

import GHC.Exts (RuntimeRep, TYPE)

-- A data field whose representation is a variable: no fixed runtime representation.
data RepBoxChirho (r :: RuntimeRep) (a :: TYPE r) = MkRepBoxChirho a

-- For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. — John 3:16 (KJV)
{-# LANGUAGE MagicHash #-}
module UnliftedFieldChirho where

import GHC.Exts (Int#)

-- A data field of a fixed unlifted representation, the shape of base's `data Int = I# Int#`.
data IntBoxChirho = MkIntBoxChirho Int#

{-# LANGUAGE DerivingStrategies #-}
newtype AgeChirho = AgeChirho Int deriving stock Show
main = print (AgeChirho 7)

{-# LANGUAGE DerivingStrategies, GeneralizedNewtypeDeriving #-}
newtype AgeChirho = AgeChirho Int deriving newtype (Show, Num)
main = print (AgeChirho 3 + 4)
